12: JEMALLOC_ALWAYS_INLINE pszind_t
13: sz_psz2ind(size_t psz) {
14: 	assert(psz > 0);
15: 	if (unlikely(psz > SC_LARGE_MAXCLASS)) {
16: 		return SC_NPSIZES;
17: 	}
18: 	/* x is the lg of the first base >= psz. */
19: 	pszind_t x = lg_ceil(psz);
20: 	/*
21: 	 * sc.h introduces a lot of size classes. These size classes are divided
22: 	 * into different size class groups. There is a very special size class
23: 	 * group, each size class in or after it is an integer multiple of PAGE.
24: 	 * We call it first_ps_rg. It means first page size regular group. The
25: 	 * range of first_ps_rg is (base, base * 2], and base == PAGE *
26: 	 * SC_NGROUP. off_to_first_ps_rg begins from 1, instead of 0. e.g.
27: 	 * off_to_first_ps_rg is 1 when psz is (PAGE * SC_NGROUP + 1).
28: 	 */
29: 	pszind_t off_to_first_ps_rg = (x < SC_LG_NGROUP + LG_PAGE) ?
30: 	    0 : x - (SC_LG_NGROUP + LG_PAGE);
31: 
32: 	/*
33: 	 * Same as sc_s::lg_delta.
34: 	 * Delta for off_to_first_ps_rg == 1 is PAGE,
35: 	 * for each increase in offset, it's multiplied by two.
36: 	 * Therefore, lg_delta = LG_PAGE + (off_to_first_ps_rg - 1).
37: 	 */
38: 	pszind_t lg_delta = (off_to_first_ps_rg == 0) ?
39: 	    LG_PAGE : LG_PAGE + (off_to_first_ps_rg - 1);
40: 
41: 	/*
42: 	 * Let's write psz in binary, e.g. 0011 for 0x3, 0111 for 0x7.
43: 	 * The leftmost bits whose len is lg_base decide the base of psz.
44: 	 * The rightmost bits whose len is lg_delta decide (pgz % PAGE).
45: 	 * The middle bits whose len is SC_LG_NGROUP decide ndelta.
46: 	 * ndelta is offset to the first size class in the size class group,
47: 	 * starts from 1.
48: 	 * If you don't know lg_base, ndelta or lg_delta, see sc.h.
49: 	 * |xxxxxxxxxxxxxxxxxxxx|------------------------|yyyyyyyyyyyyyyyyyyyyy|
50: 	 * |<-- len: lg_base -->|<-- len: SC_LG_NGROUP-->|<-- len: lg_delta -->|
51: 	 *                      |<--      ndelta      -->|
52: 	 * rg_inner_off = ndelta - 1
53: 	 * Why use (psz - 1)?
54: 	 * To handle case: psz % (1 << lg_delta) == 0.
55: 	 */
56: 	pszind_t rg_inner_off = (((psz - 1)) >> lg_delta) & (SC_NGROUP - 1);
