64: sz_pind2sz_compute(pszind_t pind) {
65: 	if (unlikely(pind == SC_NPSIZES)) {
66: 		return SC_LARGE_MAXCLASS + PAGE;
67: 	}
68: 	size_t grp = pind >> SC_LG_NGROUP;
69: 	size_t mod = pind & ((ZU(1) << SC_LG_NGROUP) - 1);
70: 
71: 	size_t grp_size_mask = ~((!!grp)-1);
72: 	size_t grp_size = ((ZU(1) << (LG_PAGE + (SC_LG_NGROUP-1))) << grp)
73: 	    & grp_size_mask;
74: 
75: 	size_t shift = (grp == 0) ? 1 : grp;
76: 	size_t lg_delta = shift + (LG_PAGE-1);
77: 	size_t mod_size = (mod+1) << lg_delta;
78: 
79: 	size_t sz = grp_size + mod_size;
80: 	return sz;
81: }
