141: sz_psz2u(size_t psz) {
142: 	if (unlikely(psz > SC_LARGE_MAXCLASS)) {
143: 		return SC_LARGE_MAXCLASS + PAGE;
144: 	}
145: 	size_t x = lg_floor((psz<<1)-1);
146: 	size_t lg_delta = (x < SC_LG_NGROUP + LG_PAGE + 1) ?
147: 	    LG_PAGE : x - SC_LG_NGROUP - 1;
